import{at as e,it as t,n,vt as r}from"./chunks/framework.BVWCHfG0.js";var i=JSON.parse(`{"title":"The\xA0styled namespace","description":"","frontmatter":{},"headers":[],"relativePath":"syntaxes/styled.md","filePath":"lib/syntaxes/styled/README.md","lastUpdated":1791105871000}`),a={name:`syntaxes/styled.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e('<h1 id="the-styled-namespace" tabindex="-1">The\xA0<code>styled</code> namespace <a class="header-anchor" href="#the-styled-namespace" aria-label="Permalink to “The\xA0styled namespace”">​</a></h1><p>The\xA0rules of\xA0the\xA0core under\xA0<code>@stylistic/styled/&lt;rule&gt;</code>, for\xA0stylesheets embedded in\xA0JavaScript as\xA0styled templates and\xA0parsed with\xA0<a href="https://github.com/hudochenkov/postcss-styled-syntax" target="_blank" rel="noreferrer"><code>postcss-styled-syntax</code></a>. They are configured in\xA0the\xA0<code>overrides</code> block naming that\xA0syntax, as\xA0<a href="/user-guide/custom-syntaxes">Custom syntaxes</a> shows.</p><p>Every rule of\xA0the\xA0core is here, with\xA0the\xA0same options and\xA0the\xA0same documentation, and\xA0plain CSS is read exactly as\xA0the\xA0core reads it. Some rules answer a\xA0styled template differently:</p><ul><li><a href="/rules/indentation"><code>indentation</code></a> counts its levels from\xA0the\xA0line the\xA0template&#39;s expression opens on\xA0rather than\xA0from\xA0the\xA0start of\xA0the\xA0line, and\xA0a\xA0template broken over\xA0lines holds its content one level deeper\xA0— save for\xA0a\xA0first node standing on\xA0the\xA0line of\xA0the\xA0backtick itself, which\xA0hangs from\xA0neither and\xA0is asked for\xA0no indentation at\xA0all; a\xA0declaration whose value embeds an\xA0expression of\xA0the\xA0host language (<code>${…}</code>) is not\xA0checked, since\xA0its lines are the\xA0host&#39;s rather than\xA0the\xA0stylesheet&#39;s.</li><li><a href="/rules/no-empty-first-line"><code>no-empty-first-line</code></a> reads the\xA0break behind the\xA0opening backtick as\xA0the\xA0end of\xA0the\xA0host&#39;s line rather than\xA0as\xA0an\xA0empty first line: an\xA0empty line is one standing between\xA0that\xA0line and\xA0the\xA0first line of\xA0the\xA0stylesheet.</li><li><a href="/rules/no-missing-end-of-source-newline"><code>no-missing-end-of-source-newline</code></a> asks for\xA0no break where the\xA0closing backtick stands on\xA0the\xA0host&#39;s line\xA0— a\xA0template not\xA0broken over\xA0lines, or\xA0one whose last line holds nothing but\xA0the\xA0backtick&#39;s indentation\xA0— and\xA0for\xA0one in\xA0front of\xA0a\xA0closing backtick ending a\xA0line of\xA0the\xA0stylesheet.</li><li><a href="/rules/no-eol-whitespace"><code>no-eol-whitespace</code></a> reads the\xA0end of\xA0a\xA0template&#39;s text as\xA0the\xA0end of\xA0a\xA0line where a\xA0break is missing in\xA0front of\xA0the\xA0closing backtick, and\xA0as\xA0no line&#39;s end where that\xA0backtick stands on\xA0the\xA0host&#39;s line: spaces in\xA0front of\xA0a\xA0backtick closing a\xA0single-line template, and\xA0the\xA0indentation of\xA0one standing on\xA0a\xA0line of\xA0its own, are the\xA0host&#39;s.</li></ul>',4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};